add_filter( 'get_avatar', 'perfectpixel_avatar_default_alt', 20, 6 );

function perfectpixel_avatar_default_alt( $avatar, $id_or_email, $size, $default, $alt, $args = array() ) {
	if ( '' !== (string) $alt || false === strpos( $avatar, "alt=''" ) && false === strpos( $avatar, 'alt=""' ) ) {
		return $avatar;
	}
	$name = '';
	if ( $id_or_email instanceof WP_Comment ) {
		$name = $id_or_email->comment_author;
	} elseif ( $id_or_email instanceof WP_User ) {
		$name = $id_or_email->display_name;
	} elseif ( $id_or_email instanceof WP_Post ) {
		$name = get_the_author_meta( 'display_name', $id_or_email->post_author );
	} elseif ( is_numeric( $id_or_email ) ) {
		$user = get_user_by( 'id', (int) $id_or_email );
		$name = $user ? $user->display_name : '';
	} elseif ( is_string( $id_or_email ) && is_email( $id_or_email ) ) {
		$user = get_user_by( 'email', $id_or_email );
		$name = $user ? $user->display_name : '';
	}
	if ( '' === $name ) {
		return $avatar;
	}
	$text = trim( trim( '{{avatar_alt_prefix}}' ) . ' ' . $name );
	return str_replace( array( "alt=''", 'alt=""' ), 'alt="' . esc_attr( $text ) . '"', $avatar );
}
